import Foundation
import Testing
import ScryCore
@testable import ScryPipeline

// The far side heard through speakers, cut from real calls of 2026-11-17 (Scribe word times, the levels of
// `audio.wav` per 50 ms in tenths of a dB, and the lag and coupling measured over the whole call).

struct EchoCase: CustomTestStringConvertible, Sendable {
    var name: String, expected: String, lag: Int, couplingDB: Double, mic: String, far: String, micDB: String, farDB: String
    var testDescription: String { name }

    /// The "You" words `withoutEcho(_:levels:)` keeps.
    var kept: String {
        func words(_ s: String, _ who: String) -> [ScrySegment] {
            s.split(separator: "|").map {
                let p = $0.split(separator: " ")
                return ScrySegment(speaker: who, start: Double(p[p.count - 2])!, end: Double(p[p.count - 1])!,
                                   text: p.dropLast(2).joined(separator: " "))
            }
        }
        func power(_ s: String) -> [Float] { s.split(separator: " ").map { Float(pow(10, Double($0)! / 100)) } }
        let segments = (words(mic, "You") + words(far, "Speaker A")).sorted { $0.start < $1.start }
        let levels = ScryLevels(mic: power(micDB), far: power(farDB), lag: lag, coupling: pow(10, couplingDB / 10))
        return ScryTranscript.withoutEcho(segments, levels: levels).filter { $0.speaker == "You" }.map(\.text).joined(separator: " ")
    }
}

