@Test(arguments: cases) func echoIsDroppedAndYourWordsKept(_ c: EchoCase) {
    #expect(c.kept == c.expected)
}

@Test func levelsMeasureTheLagAndTellSpeakersFromHeadphones() {
    // The far side talks in 1 s bursts; the mic hears it 6 frames (300 ms) later at −30 dB, over a −70 dB floor.
    let far: [Float] = (0..<4000).map { ($0 / 20) % 2 == 0 ? 0.1 : 1e-9 }
    let speakers = ScryLevels(mic: far.indices.map { $0 < 6 ? 1e-7 : far[$0 - 6] * 1e-3 + 1e-7 }, far: far)
    #expect(speakers.lag == 6 && speakers.throughSpeakers)
    #expect(abs(10 * log10(speakers.coupling!) + 30) < 1)
    let headphones = ScryLevels(mic: far.map { _ in 1e-7 }, far: far)
    #expect(!headphones.throughSpeakers)
    // Too little loud far side to measure: no coupling, so echo falls back to the 0.4 s word match.
    let quiet = ScryLevels(mic: [Float](repeating: 1e-7, count: 4000), far: [Float](repeating: 1e-9, count: 4000))
    #expect(quiet.coupling == nil && !quiet.throughSpeakers)
    let you = ScrySegment(speaker: "You", start: 1, end: 1.2, text: "Yes"), them = ScrySegment(speaker: "Speaker A", start: 1, end: 1.2, text: "Yes")
    #expect(ScryTranscript.withoutEcho([them, you], levels: quiet) == [them])
}

@Test func levelsReadBothChannelsOfACallRecording() {
    // 0.1 s, 2 channels, 16 kHz, 16-bit: the mic at half scale (power 0.25), the far side silent.
    func le(_ v: Int, _ n: Int) -> Data { Data((0..<n).map { UInt8((v >> (8 * $0)) & 0xFF) }) }
    let pcm = Data((0..<1600).flatMap { _ in [0x00, 0x40, 0x00, 0x00] as [UInt8] })
    var wav = Data("RIFF".utf8) + le(36 + pcm.count, 4) + Data("WAVEfmt ".utf8)
    wav += le(16, 4) + le(1, 2) + le(2, 2) + le(16000, 4) + le(64000, 4) + le(4, 2) + le(16, 2)
    wav += Data("data".utf8) + le(pcm.count, 4) + pcm
    let l = ScryPipeline.levels(wav)!
    #expect(l.mic.count == 2 && abs(l.mic[0] - 0.25) < 0.001 && l.far == [0, 0])
    #expect(ScryPipeline.levels(Data("not a wav".utf8)) == nil)
}

/// The first word after each pause of theirs, on a call whose echo delay changed (2026-11-24): 60 ms after theirs, and
/// loud next to a far side that was silent a moment before. The other words are yours.
@Test func theSameWordRightAfterTheirsIsEchoAndAnswersAndYourWordsStay() {
    let quiet = [Float](repeating: 1e-7, count: 4000)
    var mic = quiet
    for i in 0..<40 { mic[i] = 0.01 }   // 0–2 s: the mic is loud, the far side's level says nothing played
    let levels = ScryLevels(mic: mic, far: quiet, lag: 6, coupling: 0.0005)
    func w(_ s: String, _ t: Double, _ text: String) -> ScrySegment { ScrySegment(speaker: s, start: t, end: t + 0.1, text: text) }
    let words = [w("Speaker A", 0.20, "provided"), w("You", 0.26, "provided"),
                 w("Speaker A", 0.60, "Yeah,"), w("You", 0.66, "Yeah,"),              // a real answer can land there
                 w("Speaker A", 1.00, "phone."), w("You", 1.30, "phone"),             // 300 ms: not this rule's
                 w("You", 1.50, "prototype"), w("Speaker A", 1.56, "prototype")]      // you said it first
    #expect(ScryTranscript.withoutEcho(words, levels: levels).filter { $0.speaker == "You" }.map(\.text) == ["Yeah,", "phone", "prototype"])
}
